// The type declarations the package ships (generated by `npm run types` at pack time), as a TypeScript project that
// installed the package has them: they compile under `strict` with `skipLibCheck` off, and they take the package's
// own examples (js/test/typed-examples.ts), each held to the README or the module header that shows it.
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { copyFileSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync } from 'node:fs';
import { createRequire } from 'node:module';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { after, test } from 'node:test';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const pkg = JSON.parse(readFileSync(path.join(root, 'package.json'), 'utf8'));
// The compiler's own command, as its package.json names it (the package exports no path to it).
const typescript = path.dirname(createRequire(import.meta.url).resolve('typescript/package.json'));
const tsc = path.join(typescript, JSON.parse(readFileSync(path.join(typescript, 'package.json'), 'utf8')).bin.tsc);
const STRICT = [
  '--strict',
  '--noEmit',
  '--skipLibCheck',
  'false',
  '--target',
  'es2022',
  '--module',
  'nodenext',
  '--moduleResolution',
  'nodenext',
];
const EXAMPLES = 'js/test/typed-examples.ts';

/**
 * A project that installed the package, made once: its folder, and in its node_modules the package's package.json
 * (whose `exports` name each entry's declarations) and the declarations as `npm pack` generates them.
 */
let made = null;
function installed() {
  if (made) return made;
  const project = mkdtempSync(path.join(tmpdir(), 'xsolana-types-'));
  const types = path.join(project, 'node_modules', pkg.name, 'types');
  mkdirSync(types, { recursive: true });
  copyFileSync(path.join(root, 'package.json'), path.join(types, '../package.json'));
  execFileSync(process.execPath, [tsc, '-p', path.join(root, 'tsconfig.types.json'), '--outDir', types], { cwd: root });
  return (made = { project, types });
}
after(() => made && rmSync(made.project, { recursive: true, force: true }));

/** Compiles `files` under strict in `cwd`, or fails with what the compiler said. */
function compiles(files, cwd, what) {
  try {
    execFileSync(process.execPath, [tsc, ...STRICT, ...files], { cwd, encoding: 'utf8' });
  } catch (err) {
    assert.fail(`${what}:\n${err.stdout}`);
  }
}

test('the generated type declarations compile under strict', () => {
  const { types } = installed();
  const files = readdirSync(types, { recursive: true })
    .filter(f => /\.d\.m?ts$/.test(f))
    .map(f => path.join(types, f));
  assert.ok(files.length > 20, `only ${files.length} declaration files`);
  compiles(files, types, "the declarations don't compile");
});

test('the package’s own examples compile under strict against the declarations it ships', () => {
  const { project } = installed();
  copyFileSync(path.join(root, EXAMPLES), path.join(project, 'examples.ts'));
  compiles(['examples.ts'], project, `${EXAMPLES} doesn't compile against the shipped declarations`);
});

// Code as it is compared: without spaces, line breaks, or the comma a formatter puts before a closing bracket.
const bare = text => text.replace(/\s+/g, '').replace(/,(?=[)\]}])/g, '');
/** An example line's code: what follows it on the line (`// …`, `→ …`) and its closing `;` left out. */
const codeOf = line =>
  line
    .replace(/\s+(\/\/|→).*$/, '')
    .replace(/;$/, '')
    .trim();
/** The example lines of a module's header: its `//   ` lines above the first import that call something. */
const headerExamples = file =>
  readFileSync(path.join(root, file), 'utf8')
    .split(/^import /m)[0]
    .split('\n')
    .filter(line => /^\/\/ {3}\S/.test(line))
    .map(line => codeOf(line.slice(5)));
/** The lines of a document's `js` blocks. */
const fencedExamples = file =>
  [...readFileSync(path.join(root, file), 'utf8').matchAll(/^```js\n([\s\S]*?)^```/gm)]
    .flatMap(block => block[1].split('\n'))
    .filter(line => !line.trimStart().startsWith('//'))
    .map(codeOf);

test('each example the README and the module headers show is one of those compiled, as it is written there', () => {
  const compiled = bare(readFileSync(path.join(root, EXAMPLES), 'utf8'));
  const shown = {
    'README.md': fencedExamples('README.md'),
    'js/play/index.js': headerExamples('js/play/index.js'),
    'js/results/index.js': headerExamples('js/results/index.js'),
  };
  for (const [source, lines] of Object.entries(shown)) {
    const calls = lines.filter(line => line.includes('('));
    assert.ok(calls.length >= 3, `${source} shows ${calls.length} example lines`);
    for (const line of calls)
      assert.ok(compiled.includes(bare(line)), `${source} shows \`${line}\`, which ${EXAMPLES} does not have`);
  }
});
